## Step 2 – The standalone CLI script: `deep-lite.js`

Place this file in your `~/deepseek-cli` directory. It requires the WASM file `deepseek.wasm` to be in the same folder (copy it from `deepterm/` or keep it there and adjust the path). The script does not need `node_modules` – it uses only Node’s built‑in modules (`fs`, `readline`, `path`, `buffer`) and the WASM solver.

```javascript
#!/usr/bin/env node
// deep-lite.js – Lightweight DeepSeek CLI, no Puppeteer, uses PoW WASM

import readline from 'readline';
import { stdin as input, stdout as output } from 'process';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { Buffer } from 'buffer';

// ==== PoW solver (reused from deepterm-core) ==================================
const __dirname = path.dirname(fileURLToPath(import.meta.url));
const wasmPath = path.join(__dirname, 'deepseek.wasm');
const wasmBytes = fs.readFileSync(wasmPath);
let wasmInstance, wasmExports, memory, malloc, stack_ptr;

async function initWasm() {
  if (wasmInstance) return;
  const { instance } = await WebAssembly.instantiate(wasmBytes, {});
  wasmInstance = instance;
  wasmExports = instance.exports;
  memory = wasmExports.memory;
  malloc = wasmExports.__wbindgen_export_0;
  stack_ptr = wasmExports.__wbindgen_add_to_stack_pointer(-16);
}

function allocUtf8(str) {
  const encoder = new TextEncoder();
  const bytes = encoder.encode(str);
  const ptr = malloc(bytes.length, 1);
  const view = new Uint8Array(memory.buffer, ptr, bytes.length);
  view.set(bytes);
  return [ptr, bytes.length];
}

async function solvePow(challenge, salt, expireAt, difficulty) {
  await initWasm();
  const prefix = `${salt}_${expireAt}_`;
  const [challengePtr, challengeLen] = allocUtf8(challenge);
  const [prefixPtr, prefixLen] = allocUtf8(prefix);
  wasmExports.wasm_solve(stack_ptr, challengePtr, challengeLen, prefixPtr, prefixLen, difficulty);
  const view = new DataView(memory.buffer, stack_ptr, 16);
  const found = view.getInt32(0, true);
  const answer = view.getFloat64(8, true);
  if (found === 0) throw new Error('PoW not solved');
  return Math.floor(answer);
}

// ==== HTTP helpers ============================================================
function baseHeaders(token) {
  return {
    'accept': '*/*',
    'accept-language': 'en-US,en;q=0.9',
    'authorization': token,   // token must include "Bearer " prefix
    'priority': 'u=1, i',
    'sec-ch-ua': '"Not)A;Brand";v="8", "Chromium";v="138", "Brave";v="138"',
    'sec-ch-ua-mobile': '?0',
    'sec-ch-ua-platform': '"Windows"',
    'sec-fetch-dest': 'empty',
    'sec-fetch-mode': 'cors',
    'sec-fetch-site': 'same-origin',
    'x-app-version': '20241129.1',
    'x-client-locale': 'en_US',
    'x-client-platform': 'web',
    'x-client-version': '1.3.0-auto-resume',
  };
}

async function generatePowHeader(token, chatSessionId) {
  const resp = await fetch('https://chat.deepseek.com/api/v0/chat/create_pow_challenge', {
    method: 'POST',
    headers: {
      ...baseHeaders(token),
      'content-type': 'application/json',
      referer: `https://chat.deepseek.com/a/chat/s/${chatSessionId}`,
    },
    body: JSON.stringify({ target_path: '/api/v0/chat/completion' }),
  });
  const json = await resp.json();
  const { challenge, salt, expire_at, difficulty, signature, algorithm, target_path } = json.data.biz_data.challenge;
  const answer = await solvePow(challenge, salt, expire_at, difficulty);
  const payload = { algorithm, challenge, salt, answer, signature, target_path };
  return Buffer.from(JSON.stringify(payload)).toString('base64');
}

// ==== Core API ================================================================
async function createChatSession(token) {
  const resp = await fetch('https://chat.deepseek.com/api/v0/chat_session/create', {
    method: 'POST',
    headers: { ...baseHeaders(token), 'content-type': 'application/json' },
    body: JSON.stringify({ character_id: null }),
  });
  const json = await resp.json();
  if (!json?.data?.biz_data?.id) throw new Error('Failed to create session');
  return json;
}

async function fetchChatSessions(token) {
  const resp = await fetch('https://chat.deepseek.com/api/v0/chat_session/fetch_page', {
    headers: baseHeaders(token),
  });
  const json = await resp.json();
  return json?.data?.biz_data?.chat_sessions || [];
}

async function fetchHistoryMessages(token, sessionId) {
  const url = `https://chat.deepseek.com/api/v0/chat/history_messages?chat_session_id=${sessionId}&cache_version=-1`;
  const resp = await fetch(url, { headers: baseHeaders(token) });
  const json = await resp.json();
  return json;
}

async function* completion(token, prompt, chatSessionId, parentMessageId = null) {
  const pow = await generatePowHeader(token, chatSessionId);
  const resp = await fetch('https://chat.deepseek.com/api/v0/chat/completion', {
    method: 'POST',
    headers: {
      ...baseHeaders(token),
      'content-type': 'application/json',
      'x-ds-pow-response': pow,
      referer: `https://chat.deepseek.com/a/chat/s/${chatSessionId}`,
    },
    body: JSON.stringify({
      chat_session_id: chatSessionId,
      parent_message_id: parentMessageId,
      prompt,
      ref_file_ids: [],
      thinking_enabled: false,
      search_enabled: true,
    }),
  });

  const reader = resp.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';

  while (true) {
    const { value, done } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    const lines = buffer.split('\n');
    buffer = lines.pop() || '';   // keep incomplete line

    for (const line of lines) {
      if (!line.startsWith('data:')) continue;
      try {
        const json = JSON.parse(line.slice(5).trim());
        if (json?.o === 'replace' && typeof json.v === 'string') {
          // replace whole text – we can yield the new text
          yield { replace: json.v };
        } else if (json?.o === 'append' && typeof json.v === 'string') {
          yield { append: json.v };
        } else if (typeof json.v === 'string' && !['SEARCHING', 'FINISHED', 'ANSWER'].includes(json.v)) {
          // fallback: treat as append
          yield { append: json.v };
        }
      } catch {}
    }
  }
}

// ==== CLI logic ===============================================================
const HISTORY_FILE = path.join(__dirname, 'chat-history.json');
let chatLog = {};
if (fs.existsSync(HISTORY_FILE)) {
  try { chatLog = JSON.parse(fs.readFileSync(HISTORY_FILE, 'utf8')); } catch {}
}
function saveHistory() {
  fs.writeFileSync(HISTORY_FILE, JSON.stringify(chatLog, null, 2));
}

function printHelp() {
  console.log(`Usage: deep-lite.js [options] [prompt]

Options:
  -p, --prompt "<text>"     One-shot prompt
  -i, --interactive         Interactive session
  --session <id>            Use existing chat session ID
  --list                    List available chat sessions
  --log                     Show local chat history
  --system-prompt "<text>"  Set system prompt (not implemented)
  -h, --help                Show this help
`);
  process.exit(0);
}

// Interactive input (multiline, escape to send)
function interactivePrompt() {
  return new Promise((resolve) => {
    let buffer = [];
    let currentLine = '';
    process.stdin.setRawMode(true);
    process.stdin.resume();
    readline.emitKeypressEvents(process.stdin);
    const handler = (str, key) => {
      if (key.ctrl && key.name === 'c') {
        console.log('\n👋 Exiting.');
        process.exit();
      } else if (key.name === 'return') {
        buffer.push(currentLine);
        currentLine = '';
        process.stdout.write('\n');
      } else if (key.name === 'backspace') {
        if (currentLine.length) {
          currentLine = currentLine.slice(0, -1);
          process.stdout.clearLine(0);
          process.stdout.cursorTo(0);
          process.stdout.write(currentLine);
        }
      } else if (key.name === 'escape') {
        buffer.push(currentLine);
        process.stdin.removeListener('keypress', handler);
        process.stdin.setRawMode(false);
        resolve(buffer.join('\n').trim());
      } else if (str && str !== '\u0000') {
        currentLine += str;
        process.stdout.write(str);
      }
    };
    process.stdin.on('keypress', handler);
  });
}

async function sendPrompt(token, prompt, chatId, parentId) {
  let fullText = '';
  let currentReplace = '';

  for await (const chunk of completion(token, prompt, chatId, parentId)) {
    if (chunk.replace !== undefined) {
      // Replace the entire message (occurs with some search results)
      currentReplace = chunk.replace;
      process.stdout.write('\r' + currentReplace);   // overwrite line
      fullText = currentReplace;
    } else if (chunk.append !== undefined) {
      process.stdout.write(chunk.append);
      fullText += chunk.append;
    }
  }
  process.stdout.write('\n');
  return fullText;
}

async function runInteractive(token) {
  console.log('DeepSeek Lite – interactive mode. Type your message (Escape to send, Ctrl+C to exit).\n');
  const sessions = await fetchChatSessions(token);
  if (!sessions.length) {
    console.log('No existing sessions. Creating new one...');
  } else {
    console.log('Available sessions:');
    sessions.forEach((s, i) => console.log(`[${i+1}] ${s.title || '(untitled)'}`));
    console.log('[+] Create new session');
    const answer = await new Promise(resolve => {
      const rl = readline.createInterface({ input, output });
      rl.question('\n➡️ Choose session (or +): ', ans => { rl.close(); resolve(ans.trim()); });
    });
    if (answer === '+') {
      const newSession = await createChatSession(token);
      chatId = newSession.data.biz_data.id;
    } else {
      const idx = parseInt(answer) - 1;
      if (isNaN(idx) || idx < 0 || idx >= sessions.length) {
        console.log('Invalid choice. Exiting.');
        return;
      }
      chatId = sessions[idx].id;
    }
  }

  // Get last message ID for threading
  const history = await fetchHistoryMessages(token, chatId);
  const msgs = history?.data?.biz_data?.chat_messages || [];
  let parentId = msgs.length ? msgs[msgs.length - 1].message_id : null;

  while (true) {
    process.stdout.write('> ');
    const userInput = await interactivePrompt();
    if (!userInput) continue;

    // Update local history
    if (!chatLog[chatId]) {
      chatLog[chatId] = { title: sessions.find(s => s.id === chatId)?.title || 'New Chat', messages: [] };
    }
    chatLog[chatId].messages.push({ role: 'user', content: userInput, time: Date.now() });

    const reply = await sendPrompt(token, userInput, chatId, parentId);
    chatLog[chatId].messages.push({ role: 'assistant', content: reply, time: Date.now() });
    saveHistory();

    // Update parentId to the latest message (simplistic; real ID from response is better)
    // For simplicity, we just assume it's the last one; works for single-turn.
    // For multi-turn context, you'd need the actual message ID from the response.
    parentId = parentId; // keep same for now (you could fetch history again)
  }
}

async function oneShot(token, prompt) {
  const session = await createChatSession(token);
  const chatId = session.data.biz_data.id;
  const reply = await sendPrompt(token, prompt, chatId, null);
  // Save to history
  if (!chatLog[chatId]) chatLog[chatId] = { title: 'One-shot', messages: [] };
  chatLog[chatId].messages.push({ role: 'user', content: prompt, time: Date.now() });
  chatLog[chatId].messages.push({ role: 'assistant', content: reply, time: Date.now() });
  saveHistory();
  console.log(`\nSession ID: ${chatId}`);
}

// ==== Main ===================================================================
const args = process.argv.slice(2);
const TOKEN = process.env.DEEPSEEK_TOKEN;

if (!TOKEN) {
  console.error('❌ Environment variable DEEPSEEK_TOKEN not set.');
  console.error('   Export it as: export DEEPSEEK_TOKEN="Bearer eyJ..."');
  process.exit(1);
}

let interactive = false;
let promptText = null;
let sessionId = null;
let showList = false;
let showLog = false;

for (let i = 0; i < args.length; i++) {
  switch (args[i]) {
    case '-i': case '--interactive':
      interactive = true;
      break;
    case '-p': case '--prompt':
      promptText = args[++i];
      break;
    case '--session':
      sessionId = args[++i];
      break;
    case '--list':
      showList = true;
      break;
    case '--log':
      showLog = true;
      break;
    case '-h': case '--help':
      printHelp();
      break;
  }
}

(async () => {
  if (showLog) {
    console.log(JSON.stringify(chatLog, null, 2));
    return;
  }

  if (showList) {
    const sessions = await fetchChatSessions(TOKEN);
    sessions.forEach((s, i) => console.log(`[${i+1}] ${s.title || '(untitled)'}  (${s.id})`));
    return;
  }

  if (interactive || (!promptText && process.stdin.isTTY && !sessionId)) {
    await runInteractive(TOKEN);
  } else if (promptText) {
    await oneShot(TOKEN, promptText);
  } else if (sessionId) {
    // resume existing session with piped input or interactive if tty
    if (process.stdin.isTTY) {
      console.log(`Resuming session ${sessionId}... (type prompt, Escape to send)`);
      // interactive with existing session
      const chatId = sessionId;
      const history = await fetchHistoryMessages(TOKEN, chatId);
      const msgs = history?.data?.biz_data?.chat_messages || [];
      let parentId = msgs.length ? msgs[msgs.length - 1].message_id : null;
      while (true) {
        process.stdout.write('> ');
        const userInput = await interactivePrompt();
        if (!userInput) continue;
        if (!chatLog[chatId]) chatLog[chatId] = { title: 'Existing', messages: [] };
        chatLog[chatId].messages.push({ role: 'user', content: userInput, time: Date.now() });
        const reply = await sendPrompt(TOKEN, userInput, chatId, parentId);
        chatLog[chatId].messages.push({ role: 'assistant', content: reply, time: Date.now() });
        saveHistory();
      }
    } else {
      // piped input with session
      let piped = '';
      for await (const chunk of process.stdin) piped += chunk;
      if (piped.trim()) {
        const chatId = sessionId;
        const history = await fetchHistoryMessages(TOKEN, chatId);
        const msgs = history?.data?.biz_data?.chat_messages || [];
        let parentId = msgs.length ? msgs[msgs.length - 1].message_id : null;
        const reply = await sendPrompt(TOKEN, piped.trim(), chatId, parentId);
        if (!chatLog[chatId]) chatLog[chatId] = { title: 'Piped', messages: [] };
        chatLog[chatId].messages.push({ role: 'user', content: piped.trim(), time: Date.now() });
        chatLog[chatId].messages.push({ role: 'assistant', content: reply, time: Date.now() });
        saveHistory();
      }
    }
  } else {
    // piped input with new session
    let piped = '';
    for await (const chunk of process.stdin) piped += chunk;
    if (piped.trim()) {
      await oneShot(TOKEN, piped.trim());
    } else {
      console.error('No input provided.');
      printHelp();
    }
  }
})();
