## The script: `dslight.mjs`

```javascript
#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import readline from 'readline';
import { stdin as input, stdout as output } from 'process';
import { Buffer } from 'buffer';
import { fileURLToPath } from 'url';
import FormData from 'form-data';

// ── Configuration ──────────────────────────────────────────
const TOKEN = process.env.DEEPSEEK_TOKEN;
if (!TOKEN) {
  console.error('❌ DEEPSEEK_TOKEN environment variable not set.');
  console.error('   export DEEPSEEK_TOKEN="Bearer ey..."');
  process.exit(1);
}

const HISTORY_FILE = path.join(path.dirname(fileURLToPath(import.meta.url)), 'chat-history.json');
const WASM_FILE   = path.join(path.dirname(fileURLToPath(import.meta.url)), 'deepseek.wasm');

// ── WASM PoW solver (same as deepterm-core) ─────────────────
let wasmInstance, wasmExports, memory, malloc, stack_ptr;
async function initWasm() {
  if (wasmInstance) return;
  const wasmBytes = fs.readFileSync(WASM_FILE);
  const { instance } = await WebAssembly.instantiate(wasmBytes, {});
  wasmInstance = instance;
  wasmExports = instance.exports;
  memory = wasmExports.memory;
  malloc = wasmExports.__wbindgen_export_0;
  stack_ptr = wasmExports.__wbindgen_add_to_stack_pointer(-16);
}
function allocUtf8(str) {
  const encoder = new TextEncoder();
  const bytes = encoder.encode(str);
  const ptr = malloc(bytes.length, 1);
  const view = new Uint8Array(memory.buffer, ptr, bytes.length);
  view.set(bytes);
  return [ptr, bytes.length];
}
async function solvePow(challenge, salt, expireAt, difficulty) {
  await initWasm();
  const prefix = `${salt}_${expireAt}_`;
  const [challengePtr, challengeLen] = allocUtf8(challenge);
  const [prefixPtr, prefixLen] = allocUtf8(prefix);
  wasmExports.wasm_solve(stack_ptr, challengePtr, challengeLen, prefixPtr, prefixLen, difficulty);
  const view = new DataView(memory.buffer, stack_ptr, 16);
  const found = view.getInt32(0, true);
  const answer = view.getFloat64(8, true);
  if (found === 0) throw new Error('PoW not found');
  return Math.floor(answer);
}

// ── HTTP helpers ────────────────────────────────────────────
function headers(token) {
  return {
    'accept': '*/*',
    'accept-language': 'en-US,en;q=0.9',
    'authorization': `Bearer ${token}`,
    'sec-ch-ua': '"Not)A;Brand";v="8", "Chromium";v="138", "Brave";v="138"',
    'sec-ch-ua-mobile': '?0',
    'sec-ch-ua-platform': '"Windows"',
    'x-app-version': '20241129.1',
    'x-client-locale': 'en_US',
    'x-client-platform': 'web',
    'x-client-version': '1.3.0-auto-resume'
  };
}

async function generatePowHeader(token, sessionId, targetPath = '/api/v0/chat/completion') {
  const res = await fetch('https://chat.deepseek.com/api/v0/chat/create_pow_challenge', {
    method: 'POST',
    headers: {
      ...headers(token),
      'content-type': 'application/json',
      referer: `https://chat.deepseek.com/a/chat/s/${sessionId}`
    },
    body: JSON.stringify({ target_path: targetPath })
  });
  const json = await res.json();
  const { challenge, salt, expire_at, difficulty, signature, algorithm, target_path } = json.data.biz_data.challenge;
  const answer = await solvePow(challenge, salt, expire_at, difficulty);
  const payload = JSON.stringify({ algorithm, challenge, salt, answer, signature, target_path });
  return Buffer.from(payload).toString('base64');
}

// ── API functions ───────────────────────────────────────────
export async function createChatSession(token) {
  const r = await fetch('https://chat.deepseek.com/api/v0/chat_session/create', {
    method: 'POST',
    headers: { ...headers(token), 'content-type': 'application/json' },
    body: JSON.stringify({ character_id: null })
  });
  return r.json();
}

export async function fetchAllChatSessions(token) {
  const r = await fetch('https://chat.deepseek.com/api/v0/chat_session/fetch_page', {
    method: 'GET',
    headers: headers(token)
  });
  return r.json();
}

export async function fetchHistoryMessages(token, sessionId) {
  const r = await fetch(
    `https://chat.deepseek.com/api/v0/chat/history_messages?chat_session_id=${sessionId}&cache_version=-1`,
    { headers: headers(token) }
  );
  return r.json();
}

export async function uploadFile(token, sessionId, filePath) {
  const pow = await generatePowHeader(token, sessionId, '/api/v0/file/upload_file');
  const form = new FormData();
  const fileName = path.basename(filePath);
  form.append('file', fs.createReadStream(filePath), { filename: fileName, contentType: 'application/json' });
  const r = await fetch('https://chat.deepseek.com/api/v0/file/upload_file', {
    method: 'POST',
    headers: {
      ...form.getHeaders(),
      ...headers(token),
      'x-ds-pow-response': pow,
      'x-thinking-enabled': '0'
    },
    body: form,
  });
  return r.json();
}

// ── Completion generator with auto‑retry ─────────────────────
export async function* completion(token, prompt, chatSessionId, parentMessageId = null, retries = 3, retryDelay = 15000) {
  let attempt = 0;
  let fullReply = '';
  while (attempt <= retries) {
    const pow = await generatePowHeader(token, chatSessionId);
    const response = await fetch('https://chat.deepseek.com/api/v0/chat/completion', {
      method: 'POST',
      headers: {
        ...headers(token),
        'content-type': 'application/json',
        'x-ds-pow-response': pow,
        referer: `https://chat.deepseek.com/a/chat/s/${chatSessionId}`
      },
      body: JSON.stringify({
        chat_session_id: chatSessionId,
        parent_message_id: parentMessageId,
        prompt,
        ref_file_ids: [],
        thinking_enabled: false,
        search_enabled: true
      })
    });

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';
    fullReply = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() || '';
      for (const line of lines) {
        if (line.startsWith('data:')) {
          try {
            const json = JSON.parse(line.slice(5).trim());
            if (json?.v && !['SEARCHING', 'FINISHED', 'ANSWER'].includes(json.v)) {
              fullReply += json.v;
              yield json.v;
            }
          } catch {}
        }
      }
    }

    // Check for server busy or zero‑thought responses
    if (/server is busy|thought for 0 seconds/i.test(fullReply)) {
      if (attempt < retries) {
        console.error(`\n⚠️ Server busy. Retrying in ${retryDelay/1000}s...`);
        await new Promise(r => setTimeout(r, retryDelay));
        attempt++;
        continue;
      }
    }
    break; // success or exhausted retries
  }
}

// ── Chat history ────────────────────────────────────────────
let chatLog = {};
function loadHistory() {
  if (fs.existsSync(HISTORY_FILE)) {
    try { chatLog = JSON.parse(fs.readFileSync(HISTORY_FILE, 'utf8')); } catch {}
  }
}
function saveHistory() {
  fs.writeFileSync(HISTORY_FILE, JSON.stringify(chatLog, null, 2));
}

// ── Interactive multi‑line input (like deepterm) ────────────
function aiBanner() {
  const line = '━'.repeat(60);
  console.log(`\nType your prompt below\n[ESC] to send  [Ctrl+C] to exit\n${line}`);
}

async function interactiveCLI(sessionId, parentMsgId) {
  aiBanner();
  process.stdin.setRawMode(true);
  readline.emitKeypressEvents(process.stdin);
  let buffer = [];
  let currentLine = '';

  const onKeypress = async (str, key) => {
    if (key.name === 'return') {
      buffer.push(currentLine);
      currentLine = '';
      process.stdout.write('\n');
    } else if (key.name === 'backspace') {
      if (currentLine.length > 0) {
        currentLine = currentLine.slice(0, -1);
        process.stdout.clearLine(0);
        process.stdout.cursorTo(0);
        process.stdout.write(currentLine);
      }
    } else if (key.name === 'escape') {
      buffer.push(currentLine);
      const prompt = buffer.join('\n').trim();
      currentLine = '';
      buffer = [];
      if (prompt) {
        console.log('\n🤖 Response:\n');
        for await (const token of completion(TOKEN, prompt, sessionId, parentMsgId)) {
          process.stdout.write(token);
        }
        console.log('\n\n' + '━'.repeat(60) + '\n');
        // Update parentMsgId? Not directly known; skip for simplicity.
      } else {
        console.log('\n❌ Empty prompt.\n');
      }
    } else if (key.ctrl && key.name === 'c') {
      console.log('\n👋 Exiting.');
      process.stdin.setRawMode(false);
      process.exit();
    } else if (str && str !== '\u0000') {
      currentLine += str;
      process.stdout.write(str);
    }
  };

  process.stdin.on('keypress', onKeypress);
}

// ── CLI argument parsing ────────────────────────────────────
async function main() {
  loadHistory();
  const args = process.argv.slice(2);
  let sessionId = null, editMode = false, loopMode = false, listMode = false, showLog = false;
  let attachFile = null, promptArg = null, outputFile = null;

  for (let i = 0; i < args.length; i++) {
    const a = args[i];
    if (a === '--session' && args[i+1]) { sessionId = args[++i]; }
    else if (a === '--edit') editMode = true;
    else if (a === '--loop') loopMode = true;
    else if (a === '--list') listMode = true;
    else if (a === '--log') showLog = true;
    else if (a === '--attach' && args[i+1]) { attachFile = args[++i]; }
    else if (a === '-p' || a === '--prompt') { promptArg = args[++i]; }
    else if (a === '-i' || a === '--interactive') { /* will be handled */ }
    else if (a === '-o' || a === '--output') { outputFile = args[++i]; }
    else if (a === '-h' || a === '--help') {
      console.log(`Usage: dslight.mjs [options] [prompt]
Options:
  -p, --prompt "text"      One-shot prompt
  -i, --interactive        Interactive multi-line chat (or default if TTY)
  --attach <file>          Attach a file before prompt
  --session <ID>           Continue in an existing session
  --edit                   Edit last user message (if session loaded)
  --list                   List recent sessions
  --log                    Print chat history
  -o, --output <file>      Save last response to file
  --loop                   Read lines from stdin continuously
  -h, --help               This help`);
      return;
    }
  }

  if (showLog) { console.log(JSON.stringify(chatLog, null, 2)); return; }

  // List mode
  if (listMode) {
    const sessions = await fetchAllChatSessions(TOKEN);
    if (sessions?.data?.biz_data?.chat_sessions) {
      console.log('💬 Recent sessions:');
      sessions.data.biz_data.chat_sessions.forEach((s, i) => console.log(`[${i+1}] ${s.title || '(untitled)'} (${s.id})`));
    } else {
      console.log('❌ Could not fetch sessions.');
    }
    return;
  }

  // Interactive or TTY default
  const isTTY = process.stdin.isTTY;
  if (!promptArg && !loopMode && isTTY) {
    // Interactive session selection
    console.clear();
    console.log(`\nLogged in as: (token provided)\n`);
    const pages = await fetchAllChatSessions(TOKEN);
    const chats = pages?.data?.biz_data?.chat_sessions;
    if (!chats || chats.length === 0) {
      console.log('No existing chats. Creating new session...');
      const newChat = await createChatSession(TOKEN);
      sessionId = newChat.data.biz_data.id;
      console.log(`New session: ${sessionId}`);
    } else {
      console.log('Available sessions:');
      chats.forEach((c, i) => console.log(`[${i+1}] ${c.title || '(untitled)'}`));
      console.log('[+] New session');
      const rl = readline.createInterface({ input, output });
      const ans = await new Promise(resolve => rl.question('\n➡️ Select: ', resolve));
      rl.close();
      if (ans === '+') {
        const nc = await createChatSession(TOKEN);
        sessionId = nc.data.biz_data.id;
        console.log('✅ New session created.');
      } else {
        const idx = parseInt(ans) - 1;
        if (isNaN(idx) || idx < 0 || idx >= chats.length) { console.log('❌ Invalid.'); return; }
        sessionId = chats[idx].id;
      }
    }
    await interactiveCLI(sessionId, null);
    return;
  }

  // One-shot or piped input
  if (promptArg || !isTTY || loopMode) {
    let prompt = promptArg || '';
    if (!isTTY) {
      // piped input
      let piped = '';
      for await (const chunk of process.stdin) piped += chunk;
      prompt = prompt ? prompt + '\n' + piped.trim() : piped.trim();
    }

    if (loopMode) {
      // continuous stdin lines
      if (!sessionId) {
        const nc = await createChatSession(TOKEN);
        sessionId = nc.data.biz_data.id;
      }
      for await (const line of readline.createInterface({ input })) {
        if (line.trim()) {
          console.log('🤖 Response:');
          for await (const token of completion(TOKEN, line.trim(), sessionId, null)) {
            process.stdout.write(token);
          }
          console.log();
        }
      }
      return;
    }

    if (!prompt) { console.error('No prompt provided.'); return; }

    // File upload if --attach
    let fileIds = [];
    if (attachFile) {
      const absPath = path.resolve(attachFile);
      if (!fs.existsSync(absPath)) {
        console.error(`❌ File not found: ${absPath}`);
      } else {
        const upRes = await uploadFile(TOKEN, sessionId, absPath);
        const fileId = upRes?.data?.biz_data?.id;
        if (fileId) {
          fileIds.push(fileId);
          console.log(`📎 Attached file: ${path.basename(absPath)} (id: ${fileId})`);
        }
      }
    }

    // Create session if needed
    if (!sessionId) {
      const nc = await createChatSession(TOKEN);
      sessionId = nc.data.biz_data.id;
    }

    // Edit mode: fetch history to find last user message (limited support)
    if (editMode) {
      const hist = await fetchHistoryMessages(TOKEN, sessionId);
      const msgs = hist?.data?.biz_data?.chat_messages;
      if (msgs?.length) {
        const lastUser = msgs.filter(m => m.role === 'user').pop();
        if (lastUser) {
          // In real edit we'd need to update that message; here we simply note it
          console.log('ℹ️ Edit mode: replacing last user message (not implemented via API)');
        }
      }
    }

    // Send completion
    let fullResponse = '';
    for await (const token of completion(TOKEN, prompt, sessionId, null)) {
      process.stdout.write(token);
      fullResponse += token;
    }
    console.log(); // newline

    if (outputFile) fs.writeFileSync(outputFile, fullResponse, 'utf8');

    // Save to local history
    if (!chatLog[sessionId]) chatLog[sessionId] = { title: '', messages: [] };
    chatLog[sessionId].messages.push({ role: 'user', content: prompt, time: Date.now() });
    chatLog[sessionId].messages.push({ role: 'assistant', content: fullResponse, time: Date.now() });
    saveHistory();
  }
}

main().catch(err => {
  console.error('💥', err.message);
  process.exit(1);
});
